import 'dart:ui' as ui;
import 'package:flutter/material.dart';

/// Parses SVG path strings generated by the Mandala engine into native Flutter [ui.Path]s.
class MandalaPathParser {
  static final RegExp _tokenRegex = RegExp(
    r'([MLQAZmlqaz])|([-+]?(?:\d*\.\d+|\d+)(?:[eE][-+]?\d+)?)',
  );

  /// Parses a Mandala engine SVG path into a Flutter [ui.Path].
  static ui.Path parse(String svgPath) {
    final ui.Path path = ui.Path();
    final matches = _tokenRegex.allMatches(svgPath).toList();
    if (matches.isEmpty) return path;

    int i = 0;
    String currentCmd = '';

    while (i < matches.length) {
      final token = matches[i].group(0)!;
      if (RegExp(r'^[MLQAZmlqaz]$').hasMatch(token)) {
        currentCmd = token.toUpperCase();
        i++;
      }

      switch (currentCmd) {
        case 'M':
          if (i + 1 < matches.length) {
            final x = double.tryParse(matches[i++].group(0)!) ?? 0.0;
            final y = double.tryParse(matches[i++].group(0)!) ?? 0.0;
            path.moveTo(x, y);
            // Subsequent pairs are treated as lineTo
            currentCmd = 'L';
          }
          break;

        case 'L':
          if (i + 1 < matches.length) {
            final x = double.tryParse(matches[i++].group(0)!) ?? 0.0;
            final y = double.tryParse(matches[i++].group(0)!) ?? 0.0;
            path.lineTo(x, y);
          } else {
            i++;
          }
          break;

        case 'Q':
          if (i + 3 < matches.length) {
            final x1 = double.tryParse(matches[i++].group(0)!) ?? 0.0;
            final y1 = double.tryParse(matches[i++].group(0)!) ?? 0.0;
            final x = double.tryParse(matches[i++].group(0)!) ?? 0.0;
            final y = double.tryParse(matches[i++].group(0)!) ?? 0.0;
            path.quadraticBezierTo(x1, y1, x, y);
          } else {
            i++;
          }
          break;

        case 'A':
          if (i + 6 < matches.length) {
            final rx = double.tryParse(matches[i++].group(0)!) ?? 0.0;
            final ry = double.tryParse(matches[i++].group(0)!) ?? rx;
            i++; // skip x-axis-rotation (always 0 in engine)
            final largeArc =
                (double.tryParse(matches[i++].group(0)!) ?? 0) != 0;
            final clockwise =
                (double.tryParse(matches[i++].group(0)!) ?? 0) != 0;
            final x = double.tryParse(matches[i++].group(0)!) ?? 0.0;
            final y = double.tryParse(matches[i++].group(0)!) ?? 0.0;

            path.arcToPoint(
              Offset(x, y),
              radius: Radius.elliptical(rx, ry),
              largeArc: largeArc,
              clockwise: clockwise,
            );
          } else {
            i++;
          }
          break;

        case 'Z':
          path.close();
          break;

        default:
          i++;
          break;
      }
    }

    return path;
  }
}
